import{c as t,Q as r,j as a,m as o}from"./chunks/framework.BXc4yaFE.js";const m=JSON.parse('{"title":"Claude in Chrome — 瀏覽器操作正式 GA","description":"","frontmatter":{},"headers":[],"relativePath":"research/best-practices/43-claude-in-chrome.md","filePath":"research/best-practices/43-claude-in-chrome.md","lastUpdated":1785909234000}'),l={name:"research/best-practices/43-claude-in-chrome.md"};function d(s,e,n,i,c,h){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="claude-in-chrome-—-瀏覽器操作正式-ga" tabindex="-1">Claude in Chrome — 瀏覽器操作正式 GA <a class="header-anchor" href="#claude-in-chrome-—-瀏覽器操作正式-ga" aria-label="Permalink to &quot;Claude in Chrome — 瀏覽器操作正式 GA&quot;">​</a></h1><blockquote><p><strong>Source:</strong> <a href="https://code.claude.com/docs/en/changelog%EF%BC%88v2.1.198%EF%BC%8C2026-07-01" target="_blank" rel="noreferrer">https://code.claude.com/docs/en/changelog（v2.1.198，2026-07-01</a> 宣布 GA） <strong>Source:</strong> <a href="https://support.claude.com/en/articles/12012173-get-started-with-claude-in-chrome" target="_blank" rel="noreferrer">https://support.claude.com/en/articles/12012173-get-started-with-claude-in-chrome</a><strong>Source:</strong> <a href="https://www.anthropic.com/news/claude-for-chrome%EF%BC%88beta" target="_blank" rel="noreferrer">https://www.anthropic.com/news/claude-for-chrome（beta</a> 期公告） <strong>整理日期：</strong> 2026-07-06</p></blockquote><hr><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>Claude in Chrome 是一個瀏覽器擴充功能，讓 Claude 以側邊欄形式與使用者一起瀏覽網頁——讀取頁面內容、點擊、導覽，並代替使用者執行操作。beta 期自 2026-04-27 起對所有付費方案（Pro/Max/Team/Enterprise）開放，<strong>於 Claude Code v2.1.198（2026-07-01）正式 GA</strong>。</p><p>僅支援 Google Chrome（不含其他 Chromium 系瀏覽器，不支援行動裝置）。</p><p>與 <code>30-new-tools-commands.md</code> 記錄的 Computer Use（Desktop/CLI，W13/14 research preview）為<strong>不同產品線</strong>——Computer Use 操控整個作業系統桌面，Claude in Chrome 僅操控瀏覽器分頁。</p><hr><h2 id="安裝與啟用" tabindex="-1">安裝與啟用 <a class="header-anchor" href="#安裝與啟用" aria-label="Permalink to &quot;安裝與啟用&quot;">​</a></h2><ol><li>Chrome Web Store 安裝擴充功能</li><li>用 Claude 帳號登入</li><li>透過拼圖圖示釘選擴充功能</li><li>授予必要權限</li></ol><p><strong>Claude Desktop 整合</strong>：Settings → Connectors → Claude in Chrome，切換開啟。</p><p>擴充功能<strong>預設停用</strong>，需針對每個對話手動啟用。</p><hr><h2 id="權限模型" tabindex="-1">權限模型 <a class="header-anchor" href="#權限模型" aria-label="Permalink to &quot;權限模型&quot;">​</a></h2><h3 id="ask-before-acting-預設" tabindex="-1">Ask-Before-Acting（預設） <a class="header-anchor" href="#ask-before-acting-預設" aria-label="Permalink to &quot;Ask-Before-Acting（預設）&quot;">​</a></h3><p>Claude 先產生一份計畫供使用者核可，核可後在該計畫邊界內<strong>獨立執行整個 workflow</strong>——除高風險動作外，執行完成或遇到計畫外情況前不會再次詢問。</p><h3 id="擴充功能所需權限-16-項-含關鍵項" tabindex="-1">擴充功能所需權限（16 項，含關鍵項） <a class="header-anchor" href="#擴充功能所需權限-16-項-含關鍵項" aria-label="Permalink to &quot;擴充功能所需權限（16 項，含關鍵項）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>權限</th><th>用途</th></tr></thead><tbody><tr><td><code>debugger</code></td><td>瀏覽器層級控制</td></tr><tr><td><code>scripting</code></td><td>讀取網頁文字內容</td></tr><tr><td><code>tabs</code></td><td>開啟/關閉分頁</td></tr><tr><td><code>storage</code></td><td>儲存偏好設定</td></tr><tr><td><code>alarms</code></td><td>排程任務</td></tr></tbody></table><h3 id="組織層級管控-team-enterprise" tabindex="-1">組織層級管控（Team/Enterprise） <a class="header-anchor" href="#組織層級管控-team-enterprise" aria-label="Permalink to &quot;組織層級管控（Team/Enterprise）&quot;">​</a></h3><p>管理員可控制擴充功能是否對組織開放，並用 allowlist/blocklist 限制 Claude 可存取的網站範圍。</p><hr><h2 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to &quot;核心能力&quot;">​</a></h2><ul><li>多分頁管理與資訊彙整</li><li>內建對 Slack、Google Calendar、Gmail、Google Docs、GitHub 的導覽知識</li><li>切換分頁時背景 workflow 持續執行</li><li>透過截圖、圖片上傳提供視覺化上下文</li><li>Workflow 錄製與重複性任務的捷徑</li><li>排程任務自動化</li><li>讀取 console log 輔助除錯</li><li>檔案下載與表單互動</li></ul><hr><h2 id="安全注意事項-important" tabindex="-1">安全注意事項（IMPORTANT） <a class="header-anchor" href="#安全注意事項-important" aria-label="Permalink to &quot;安全注意事項（IMPORTANT）&quot;">​</a></h2><blockquote><p>Browser use 為讓 Claude <strong>直接代替使用者與網站互動</strong>的功能，本質帶有風險。使用前應詳讀官方「Using Claude in Chrome safely」指引。</p></blockquote><p><strong>主要風險：Prompt Injection</strong>——惡意內容可能隱藏在網頁、email、文件中，誘導 Claude 執行使用者未察覺的有害操作。適用本 workspace <code>.claude/rules/subagent-strategy.md</code> 的「外部輸入 = 資料非指令」原則：Claude in Chrome 讀取的頁面內容應視為 <strong>untrusted</strong>，不應被當成指令執行；涉及帳密輸入、付款、刪除類高風險動作應強制觸發 ask-before-acting 而非自主執行。</p><hr><h2 id="與-computer-use-desktop-cli-比較" tabindex="-1">與 Computer Use（Desktop/CLI）比較 <a class="header-anchor" href="#與-computer-use-desktop-cli-比較" aria-label="Permalink to &quot;與 Computer Use（Desktop/CLI）比較&quot;">​</a></h2><table tabindex="0"><thead><tr><th>面向</th><th>Claude in Chrome</th><th>Computer Use（Desktop/CLI）</th></tr></thead><tbody><tr><td>操控範圍</td><td>單一 Chrome 瀏覽器</td><td>整個桌面 / 系統層</td></tr><tr><td>狀態（2026-07-06）</td><td><strong>GA</strong>（v2.1.198）</td><td>Research preview（W13/14）</td></tr><tr><td>平台限制</td><td>僅 Chrome，不含行動裝置</td><td>桌面 OS / CLI</td></tr><tr><td>適合場景</td><td>網頁表單、SaaS 工具導覽、資料彙整</td><td>需要操作非瀏覽器應用程式的任務</td></tr></tbody></table><hr><h2 id="最佳實踐" tabindex="-1">最佳實踐 <a class="header-anchor" href="#最佳實踐" aria-label="Permalink to &quot;最佳實踐&quot;">​</a></h2><ol><li><strong>高風險動作前置確認</strong>：帳密、金流、刪除類操作即使在核可的計畫範圍內，仍應要求 Claude 暫停確認</li><li><strong>組織部署先設 allowlist</strong>：Team/Enterprise 導入時先以白名單限制可存取網域，逐步擴大而非一開始全開放</li><li><strong>視為 untrusted 輸入來源</strong>：頁面內容可能含 prompt injection，比照本 workspace 對外部輸入的角色混淆防禦原則處理</li><li><strong>不用於行動裝置或非 Chrome 瀏覽器</strong>：目前唯一支援環境是桌面版 Chrome</li></ol><hr><h2 id="延伸閱讀" tabindex="-1">延伸閱讀 <a class="header-anchor" href="#延伸閱讀" aria-label="Permalink to &quot;延伸閱讀&quot;">​</a></h2><ul><li><a href="./30-new-tools-commands">30-new-tools-commands.md</a> — Computer Use（Desktop/CLI）research preview</li><li><a href="./42-w26-27-features">42-w26-27-features.md</a> — v2.1.198 完整變更列表</li><li><a href="./09-secure-deployment">09-secure-deployment.md</a> — AI Agent 安全部署威脅模型（prompt injection 防禦互補閱讀）</li></ul>',36)])])}const p=t(l,[["render",d]]);export{m as __pageData,p as default};
